using Microsoft.EntityFrameworkCore;

namespace mvc
{
    // щоб підключитися до бази даних через Entity Framework, необхідний контекст даних
    // контекст даних представляє собою клас, похідний від класу DbContext
    public class MovieContext : DbContext
    {
        public DbSet<Movie> Movies { get; set; } // набір сутностей Student, який буде відображено в таблицю Students (ORM)
        public MovieContext(DbContextOptions<MovieContext> options) // конструктор, що приймає параметри підключення
        // options буде отриманий із Program.cs завдяки механізму впровадження залежностей (Dependency Injection)
           : base(options) // передаємо параметри базовому класу DbContext
        {
            if (Database.EnsureCreated()) // якщо база даних ще не створена — створюємо її (одноразово)
            {
                Movies?.Add(new Movie { Name = "Атака титанов", director = "Тэцуро Араки", genre = "Аниме, фэнтези", poster = "https://localhost:7045/img/Photo1.jpg", description = "Человечество на протяжении многих лет живёт за огромными стенами, которые защищают последние города от гигантов — таинственных существ, пожирающих людей. После неожиданного нападения одного из самых огромных титанов привычный мир рушится. Эрен Йегер вместе со своими друзьями вступает в борьбу за выживание человечества и постепенно узнаёт страшную правду о происхождении титанов и мире за стенами." });

                Movies?.Add(new Movie { Name = "Hunter x Hunter", director = "Хироси Кодзина", genre = "Аниме, приключения", poster = "/img/Photo2.jpg", description = "Двенадцатилетний Гон Фрикс узнаёт, что его отец, которого он считал давно исчезнувшим, является легендарным Охотником. Чтобы найти его, Гон отправляется в опасное путешествие и проходит сложнейший экзамен на звание Охотника. По пути он встречает новых друзей, сталкивается с могущественными противниками и постепенно открывает для себя огромный и опасный мир." });

                Movies?.Add(new Movie { Name = "Первородный грех Такопи", director = "Синъя Иноуэ", genre = "Аниме, драма", poster = "/img/Photo3.jpg", description = "Добродушный инопланетянин Такопи прибывает на Землю с планеты Happy, чтобы распространять счастье. Здесь он знакомится с тихой девочкой Сидзукой, жизнь которой оказывается гораздо сложнее, чем он мог представить. Используя необычные устройства своего народа, Такопи пытается решить её проблемы и вернуть ей улыбку, однако его наивное вмешательство приводит к тяжёлым и неожиданным последствиям." });

                Movies?.Add(new Movie { Name = "Hearts of Iron IV", director = "Paradox Development Studio", genre = "Глобальная стратегия", poster = "/img/Photo4.jpg", description = "Hearts of Iron IV — глобальная стратегическая игра, действие которой происходит в период Второй мировой войны. Игрок может взять под управление практически любое государство, развивать экономику и промышленность, создавать армии, заниматься дипломатией и принимать решения, способные изменить ход мировой истории. Победа зависит не только от военной силы, но и от грамотного управления ресурсами, технологиями и политикой." });

                Movies?.Add(new Movie { Name = "Человек-паук: Нет пути домой", director = "Джон Уоттс", genre = "Фантастика, боевик", poster = "/img/Photo5.jpg", description = "После того как весь мир узнаёт, что Человек-паук на самом деле Питер Паркер, его обычная жизнь полностью меняется. Пытаясь вернуть свою тайну, Питер обращается за помощью к Доктору Стрэнджу, но заклинание выходит из-под контроля. В результате в его мир начинают попадать опасные злодеи и герои из других вселенных, а Питеру приходится столкнуться с самым серьёзным испытанием в своей жизни." }); 

                Movies?.Add(new Movie { Name = "Рик и Морти", director = "Дэн Хармон и Джастин Ройланд", genre = "Мультсериал, фантастика, комедия", poster = "/img/Photo6.jpg", description = "Рик Санчес — гениальный, но эксцентричный учёный, который постоянно отправляется в опасные путешествия по различным планетам, измерениям и альтернативным реальностям. Вместе с ним путешествует его внук Морти, которому приходится сталкиваться с невероятными и часто опасными последствиями экспериментов своего деда. Сериал сочетает научную фантастику, юмор и истории о семье." });

                Movies?.Add(new Movie { Name = "Age of History II", director = "Лукаш Яковский", genre = "Глобальная стратегия", poster = "/img/Photo7.jpg", description = "Age of History II — глобальная стратегическая игра, охватывающая огромный период истории человечества от древних цивилизаций до далёкого будущего. Игрок может выбрать одну из множества стран и цивилизаций, развивать её территорию, заключать союзы, вести войны и использовать дипломатию. Главная цель — привести своё государство к процветанию, объединить мир или завоевать его." }); 

                Movies?.Add(new Movie { Name = "Age of History III", director = "Лукаш Яковский", genre = "Глобальная стратегия", poster = "/img/Photo8.jpg", description = "Age of History III предлагает игроку пройти через всю историю человеческой цивилизации — от первых государств до далёкого будущего. Можно управлять как огромными империями, так и небольшими народами, развивать технологии, улучшать экономику, создавать армии и вести дипломатические отношения. Решения игрока определяют, станет ли его государство могущественной мировой державой или исчезнет в ходе многочисленных конфликтов." }); 
                SaveChanges(); // зберігаємо початкові дані в базу
            }
        }
    }
}